INSERT INTO `solicitudes` VALUES (1,'FI-2026-0001',7,20,4,'Corrección de acta — Física Clásica gpo. 03','Se solicita habilitar el acta E63-101 del grupo 03 de Física Clásica para corregir la calificación del alumno con cuenta 1826354, conforme al dictamen del Consejo Académico.','alta','en_proceso','2026-07-12 05:53:27','2026-07-12 05:53:27'),(2,'FI-2026-0002',7,22,4,'Canalización de alumnos en riesgo académico','Se remite listado de 5 alumnos de tercer semestre con reprobación consecutiva para asignación de tutor y plan de seguimiento.','media','pendiente','2026-07-12 05:53:27','2026-07-12 05:53:27'),(3,'FI-2026-0003',20,18,5,'Constancias de 100% de créditos — julio 2026','Se envían 12 constancias de créditos concluidos para iniciar trámites de evaluación profesional del periodo 2026-B.','media','resuelta','2026-07-12 05:53:27','2026-07-12 05:53:27'),(4,'FI-2026-0004',14,25,8,'Requerimiento de insumos de laboratorio','Compra de reactivos y material de ensayo para el proyecto SNII-4521 del Centro de Investigación en Ingeniería Estructural. Presupuesto estimado: $48,500 MXN.','alta','pendiente','2026-07-12 05:53:27','2026-07-12 05:53:27'),(5,'FI-2026-0005',7,20,4,'Solicitud de listas de alumnos 2026-B','Se solicitan las listas oficiales de alumnos inscritos del periodo 2026-B de los grupos 01 a 05 de la licenciatura en Ingeniería en Computación para la planeación docente.','media','resuelta','2026-07-12 06:03:17','2026-07-12 06:04:48');
